 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    def regularity(indices):
        if len(indices) < 2:
            return 0.0, 0.0
        gaps = [b - a for a, b in zip(indices, indices[1:])]
        freq = Counter(gaps)
        mode_gap, mode_count = freq.most_common(1)[0]
        return mode_count / len(gaps), sum(gaps) / len(gaps)

    candidates = []
    for color in counts:
        if color == background:
            continue
        rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.65 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.65 * h]
        if len(rows) < 2 or len(cols) < 2:
            continue
        score = 0.0
        for indices, density in (
            (rows, sum(sum(v == color for v in grid[r]) / w for r in rows) / len(rows)),
            (cols, sum(sum(grid[r][c] == color for r in range(h)) / h for c in cols) / len(cols)),
        ):
            reg, gap = regularity(indices)
            # Separators recur at a stride greater than one; the common fill
            # color instead occupies long, irregular runs between separators.
            spacing = max(0.0, (gap - 1.0) / (gap + 1.0))
            score += density * reg * spacing
        candidates.append((score, color, rows, cols))
    if not candidates:
        raise ValueError('Could not identify grid separators')
    _, line_color, row_lines, col_lines = max(candidates)

    out = []
    for ri in range(len(row_lines) - 1):
        outrow = []
        for ci in range(len(col_lines) - 1):
            corners = (grid[row_lines[ri]][col_lines[ci]],
                       grid[row_lines[ri]][col_lines[ci + 1]],
                       grid[row_lines[ri + 1]][col_lines[ci]],
                       grid[row_lines[ri + 1]][col_lines[ci + 1]])
            if corners[0] != line_color and all(v == corners[0] for v in corners):
                outrow.append(corners[0])
            else:
                outrow.append(background)
        out.append(outrow)
    return out
